namespace QuizBattle { public class Player { public string Name { get; set; } public int Score { get; private set; } public int CorrectAnswers { get; private set; } public int CurrentStreak { get; private set; } public Player(string name) { Name = name; Score = 0; CorrectAnswers = 0; CurrentStreak = 0; } public void AddCorrectAnswer(int basePoints) { CorrectAnswers++; CurrentStreak++; int bonusPoints = CurrentStreak > 1 ? 5 : 0; Score += basePoints + bonusPoints; } public void ResetStreak() { CurrentStreak = 0; } } }